<script lang="ts">
  import type { Card, Validation } from './types';
  export let card: Card;
  export let validation: Validation | null;
  export let onback: () => void;
  export let onprevious: (() => void) | null = null;
  export let onnext: (() => void) | null = null;
  export let generatedAt = '';
  const factorText = (value: number, kind: string) => value < 0.98 ? `${Math.round((1-value)*100)}% easier than average ${kind}` : value > 1.02 ? `${Math.round((value-1)*100)}% harder than average ${kind}` : `Neutral ${kind}`;
  const confidenceExplanation = (report: Validation | null) => {
    if (!report?.confidence_calibration) return 'Confidence calibration is unavailable for this run, so treat the label as provisional.';
    if (report.confidence_calibration.tiers_validated) return `The ${card.confidence} label is a validation-gated uncertainty tier learned from walk-forward results.`;
    return 'The candidate uncertainty tiers did not pass the later-date audit, so high confidence is withheld; complete five-start histories inside the candidate-medium boundary are medium, while unusually uncertain or shorter histories are low.';
  };
  const favorableDrivers = () => card.drivers.filter(driver => driver.impact === 'positive');
  const riskDrivers = () => card.drivers.filter(driver => driver.impact === 'negative');
  const outlookLabel = () => card.projected_fip < 3.7 ? 'Favorable' : card.projected_fip < 4.5 ? 'Mixed' : 'Risky';
</script>

<main class="pitcher-page">
  <div class="detail-navigation"><button class="back-button" onclick={onback}>← Back to slate</button><div><button onclick={() => onprevious?.()} disabled={!onprevious}>← Previous</button><button onclick={() => onnext?.()} disabled={!onnext}>Next →</button></div></div>
  <header class="detail-header"><div><p class="kicker">Next-start analysis</p><h1>{card.pitcher_name}</h1><p>{card.pitcher_team_name} · {card.pitcher_hand ?? '—'}HP · MLBAM {card.pitcher_id}</p></div><span class="confidence confidence-{card.confidence}">{card.confidence} confidence</span></header>
  <section class="matchup-banner"><div><span>Matchup</span><b>{card.home ? 'vs' : '@'} {card.opponent_team_name}</b></div><div><span>Date</span><b>{card.target_game_date}</b></div><div><span>Venue</span><b>{card.venue_name}</b></div><div><span>Rest</span><b>{card.rest_days} days</b></div></section>

  <section class="detail-hero"><div class="hero-number"><span>Projected FIP</span><strong>{card.projected_fip.toFixed(2)}</strong><small>{card.projected_fip < 3.7 ? 'Favorable run-prevention outlook' : card.projected_fip < 4.5 ? 'Mixed run-prevention outlook' : 'Higher run risk'}</small></div><div class="hero-runs"><span>Expected runs allowed · predictive distribution</span><div class="distribution"><div><b>{card.expected_runs_low.toFixed(1)}</b><small>5th</small></div><div><b>{card.expected_runs_p25.toFixed(1)}</b><small>25th</small></div><div class="distribution-base"><strong>{card.expected_runs_base.toFixed(1)}</strong><small>Base</small></div><div><b>{card.expected_runs_p75.toFixed(1)}</b><small>75th</small></div><div><b>{card.expected_runs_high.toFixed(1)}</b><small>95th</small></div></div></div></section>

  <section class="workload-projections"><div><span>Expected innings</span><strong>{card.expected_innings.toFixed(1)}</strong><p>90% range {card.expected_innings_low.toFixed(1)}–{card.expected_innings_high.toFixed(1)}</p></div><div><span>Expected strikeouts</span><strong>{card.expected_strikeouts.toFixed(1)}</strong><p>90% range {card.expected_strikeouts_low.toFixed(1)}–{card.expected_strikeouts_high.toFixed(1)}</p></div>{#if validation}<div class="workload-validation"><span>Walk-forward validation</span><p>IP MAE <b>{validation.innings_mae.toFixed(2)}</b> · coverage <b>{(validation.calibrated_innings_interval_coverage*100).toFixed(0)}%</b></p><p>K MAE <b>{validation.strikeouts_mae.toFixed(2)}</b> · coverage <b>{(validation.calibrated_strikeouts_interval_coverage*100).toFixed(0)}%</b></p></div>{/if}</section>

  <section class="outlook-summary"><span>What this means</span><p>{card.outlook_summary}</p></section>

  <section class="why-projection"><div class="why-verdict"><span>Model verdict</span><h2>{outlookLabel()} run-prevention outlook</h2><p>{card.judgment}</p></div><div class="driver-groups"><div class="driver-group helps"><h3>Working in his favor</h3>{#if favorableDrivers().length}<ul>{#each favorableDrivers() as driver}<li>{driver.label}</li>{/each}</ul>{:else}<p>No strong favorable signal.</p>{/if}</div><div class="driver-group risks"><h3>Working against him</h3>{#if riskDrivers().length}<ul>{#each riskDrivers() as driver}<li>{driver.label}</li>{/each}</ul>{:else}<p>No strong risk signal.</p>{/if}</div></div></section>

  <section class="data-status" aria-label="Projection data status"><div><span>Starter status</span><b><i></i>{card.starter_status}</b></div><div><span>Pitching data through</span><b>{card.data_through}</b></div><div><span>History available</span><b>{card.history_starts} starts</b></div><div><span>Projection generated</span><b>{generatedAt ? new Date(generatedAt).toLocaleString() : 'This run'}</b></div></section>
  {#if card.data_warnings.length}<div class="data-warnings">{#each card.data_warnings as warning}<p>! {warning}</p>{/each}</div>{/if}

  <div class="detail-grid"><section class="detail-panel"><div class="panel-title"><h2>Recent form</h2><span>Last {card.starts_used} starts</span></div><div class="detail-stats"><div><span>K%</span><b>{(card.recent_k_rate*100).toFixed(1)}%</b></div><div><span>BB%</span><b>{(card.recent_bb_rate*100).toFixed(1)}%</b></div><div><span>HR/9</span><b>{card.recent_hr_per_9.toFixed(2)}</b></div><div><span>WHIP</span><b>{card.recent_whip.toFixed(2)}</b></div><div><span>ER/9</span><b>{card.recent_er_per_9.toFixed(2)}</b></div><div><span>GB%</span><b>{(card.recent_ground_ball_pct*100).toFixed(1)}%</b></div><div><span>FB velocity</span><b>{card.recent_fastball_velocity?.toFixed(1) ?? '—'} <small>mph</small></b></div></div></section>

  <section class="detail-panel"><div class="panel-title"><h2>Next-start context</h2><span>1.00 is league neutral</span></div><div class="factor-detail"><div><span>Park factor</span><b>{card.park_factor.toFixed(3)}</b><p>{factorText(card.park_factor, 'run environment')}</p></div><div><span>Opponent factor</span><b>{card.opponent_offense_factor.toFixed(3)}</b><p>{factorText(card.opponent_offense_factor, 'opponent split')}</p></div></div></section>

  <section class="detail-panel"><div class="panel-title"><h2>Uncertainty and use</h2><span>Research-grade output</span></div><p class="explanation">{confidenceExplanation(validation)} Use <strong>{card.expected_runs_base.toFixed(2)}</strong> as the starter input to a team model, while preserving {card.expected_runs_low.toFixed(2)}–{card.expected_runs_high.toFixed(2)} for scenario analysis. Innings and strikeouts are independently trained expectations, not conversions from projected runs.</p></section>

  <section class="detail-panel reliability-panel"><div class="panel-title"><h2>Model track record</h2><span>Walk-forward results</span></div>{#if validation}<div class="reliability-grid"><div><span>FIP error</span><b>{validation.fip_mae.toFixed(2)}</b><small>Mean absolute error</small></div><div><span>Runs error</span><b>{validation.runs_mae.toFixed(2)}</b><small>Mean absolute error</small></div><div><span>Run-band coverage</span><b>{(validation.calibrated_runs_interval_coverage*100).toFixed(0)}%</b><small>Target: 90%</small></div><div><span>Confidence tiers</span><b>{validation.confidence_calibration.tiers_validated ? 'Reliable' : 'Not reliable'}</b><small>{validation.confidence_calibration.tiers_validated ? 'Predictive on later games' : 'Weren’t reliable on later games'}</small></div></div>{:else}<p class="explanation">Validation results are unavailable for this run.</p>{/if}</section></div>

  <section class="history-panel"><div class="panel-title"><div><h2>Recent starts</h2><p>Game-by-game results behind the rolling form</p></div><span>Most recent first</span></div><div class="history-table"><div class="history-head"><span>Date</span><span>Opponent</span><span>IP</span><span>P</span><span>BF</span><span>H</span><span>HR</span><span>ER</span><span>K</span><span>BB</span><span>FIP</span></div>{#each card.recent_starts as start}<div class="history-row"><time>{start.game_date}</time><b>{start.home ? 'vs' : '@'} {start.opponent_name}</b><span>{start.innings_pitched.toFixed(1)}</span><span>{start.pitch_count ?? '—'}</span><span>{start.batters_faced}</span><span>{start.hits}</span><span>{start.home_runs}</span><span>{start.earned_runs}</span><span>{start.strikeouts}</span><span>{start.walks}</span><span>{start.fip.toFixed(2)}</span></div>{/each}</div></section>

  <section class="comparison-panel"><div class="panel-title"><div><h2>Recent form vs season</h2><p>Rates are weighted by batters faced or innings pitched</p></div><span>{card.season_form.starts} season starts</span></div><div class="comparison-table"><div><span>Window</span><span>K%</span><span>BB%</span><span>HR/9</span><span>WHIP</span><span>ER/9</span></div><div><b>Last {card.starts_used}</b><span>{(card.recent_k_rate*100).toFixed(1)}%</span><span>{(card.recent_bb_rate*100).toFixed(1)}%</span><span>{card.recent_hr_per_9.toFixed(2)}</span><span>{card.recent_whip.toFixed(2)}</span><span>{card.recent_er_per_9.toFixed(2)}</span></div><div><b>Season</b><span>{(card.season_form.k_rate*100).toFixed(1)}%</span><span>{(card.season_form.bb_rate*100).toFixed(1)}%</span><span>{card.season_form.hr_per_9.toFixed(2)}</span><span>{card.season_form.whip.toFixed(2)}</span><span>{card.season_form.er_per_9.toFixed(2)}</span></div></div></section>
</main>
